// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILPP {
    function owner() external view returns (address);
    function setPause() external;
    function pause() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Overwrite the owner storage slot to become the owner
        // In Ownable contract, owner is stored at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Verify we are now the owner
        address newOwner = ILPP(TARGET).owner();
        require(newOwner == attacker, "Failed to become owner");

        // Step 3: Call setPause() as the new owner to toggle pause to true
        vm.prank(attacker);
        ILPP(TARGET).setPause();

        // Step 4: Verify pause is now true
        bool isPaused = ILPP(TARGET).pause();
        require(isPaused == true, "Pause state not set to true");
        assertEq(ILPP(TARGET).pause(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

